import java.lang.ref.PhantomReference;
import java.lang.ref.Reference;
import java.lang.ref.ReferenceQueue;
import java.lang.ref.SoftReference;
import java.lang.ref.WeakReference;
import java.util.WeakHashMap;
import java.util.function.BooleanSupplier;

public class Main {
    static boolean waitForGc(BooleanSupplier condition) throws InterruptedException {
        for (int i = 0; i < 20; i++) {
            if (condition.getAsBoolean()) return true;
            System.gc();
            byte[] pressure = new byte[512 * 1024];
            if (pressure.length == 0) System.out.println();
            Thread.sleep(50);
        }
        return condition.getAsBoolean();
    }

    public static void main(String[] args) throws Exception {
        Object strong = new Object();
        WeakReference<Object> weak = new WeakReference<>(strong);
        System.gc();
        assert weak.get() != null;
        strong = null;
        boolean weakCleared = waitForGc(() -> weak.get() == null);
        System.out.println("weak cleared: " + weakCleared);
        assert weakCleared;

        WeakHashMap<Object, String> map = new WeakHashMap<>();
        Object key = new Object();
        map.put(key, "metadata");
        key = null;
        boolean mapCleared = waitForGc(() -> {
            map.size();
            return map.isEmpty();
        });
        System.out.println("weak map cleared: " + mapCleared);
        assert mapCleared;

        SoftReference<byte[]> soft = new SoftReference<>(new byte[1024]);
        System.out.println("soft currently available: " + (soft.get() != null));

        ReferenceQueue<Object> queue = new ReferenceQueue<>();
        Object target = new Object();
        WeakReference<Object> queuedWeak = new WeakReference<>(target, queue);
        target = null;
        Reference<?>[] polled = new Reference<?>[1];
        boolean enqueued = waitForGc(() -> {
            polled[0] = queue.poll();
            return polled[0] != null;
        });
        System.out.println("weak queued: " + enqueued);
        assert enqueued;
        assert polled[0] == queuedWeak;

        ReferenceQueue<Object> phantomQueue = new ReferenceQueue<>();
        PhantomReference<Object> phantom = new PhantomReference<>(new Object(), phantomQueue);
        assert phantom.get() == null;
        System.out.println("phantom get is null: " + (phantom.get() == null));

        ThreadLocal<byte[]> threadLocal = new ThreadLocal<>();
        threadLocal.set(new byte[1024]);
        threadLocal.remove();
        System.out.println("threadLocal remove called");
    }
}
